#include <iostream>
#include <vector>
#include <string>
#include <unordered_set>
using namespace std;

int main() {
    vector<string> g(9);
    for (int i = 0; i < 9; i++) {
        cin >> g[i];
    }

    unordered_set<string> seen;
    bool ok = true;
    for (int i = 0; i < 9; i++) {
        for (int j = 0; j < 9; j++) {
            char d = g[i][j];
            if (d == '.') continue;
            string keys[3] = {string("r") + to_string(i) + d, string("c") + to_string(j) + d,
                              string("b") + to_string(i / 3) + to_string(j / 3) + d};
            for (const string& key : keys) {
                if (seen.count(key)) ok = false;
                seen.insert(key);
            }
        }
    }
    cout << (ok ? "yes" : "no") << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] g = new String[9];
        for (int i = 0; i < g.length; i++) {
            g[i] = sc.next();
        }

        Set<String> seen = new HashSet<>();
        boolean ok = true;
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                char d = g[i].charAt(j);
                if (d == '.') continue;
                String[] keys = {"r" + i + d, "c" + j + d, "b" + (i / 3) + (j / 3) + d};
                for (String key : keys) {
                    if (!seen.add(key)) ok = false;
                }
            }
        }
        System.out.println(ok ? "yes" : "no");
    }
}
